    }

    async fn get_current_time_entry_minimal(&self) -> ResultWithDefaultError<Option<TimeEntry>> {
        let network_entry = match self.get_current_network_time_entry().await? {
            Some(entry) => entry,
            None => return Ok(None),
        };

        Ok(Some(TimeEntry {
            id: network_entry.id,
            description: network_entry.description,
            start: network_entry.start,
            stop: network_entry.stop,
            duration: network_entry.duration,
            billable: network_entry.billable,
            workspace_id: network_entry.workspace_id,
            tags: network_entry.tags.unwrap_or_default(),
            project: None,
            task: None,
            created_with: network_entry.created_with,
        }))
    }

    async fn stop_time_entry(
        &self,
        workspace_id: i64,
        time_entry_id: i64,
    ) -> ResultWithDefaultError<TimeEntry> {
        let url = format!(
            "{}/workspaces/{}/time_entries/{}/stop",
            self.base_url, workspace_id, time_entry_id
        );
        let network_entry = self.patch_without_body::<NetworkTimeEntry>(url).await?;
        Ok(self.hydrate_single_network_entry(network_entry).await)
            billable: false,
            description: "".to_string(),
            duration: -start.timestamp(),
            project: None,
            start,
            stop: None,
            tags: Vec::new(),
            task: None,
            workspace_id: -1,
        }
    }
}

impl std::fmt::Display for TimeEntry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
        let time_str = match self.stop {
            Some(stop) => {
                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
                let cross_day = local_stop.date_naive() != local_start.date_naive();
                if cross_day {
                    format!(
                        "{} ~ {}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%m-%d %H:%M")
                    )
                } else {
                    format!(
                        "{}~{}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%H:%M")
                    )
                }
            }
            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
        };
        let summary = format!(
            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
            "{} {} {} [{}]{} –  {}{} {}",
            self.id,
            time_str,
            if self.billable {
                "$".green().bold().to_string()
            } else {
                " ".to_string()
            },
","exit_code":0}

